#include <iostream>
#include <memory>

struct SimpleNode {
    int data;
    std::unique_ptr<SimpleNode> next;
};

int main() {
    // Creating a 3-node linked list using modern C++ smart pointers
    auto head = std::make_unique<SimpleNode>(SimpleNode{17, nullptr});
    head->next = std::make_unique<SimpleNode>(SimpleNode{29, nullptr});
    head->next->next = std::make_unique<SimpleNode>(SimpleNode{93, nullptr});

    // Sequential traversal
    const SimpleNode* current = head.get();
    std::cout << "List elements: ";
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->next.get();
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>

struct ListNode {
    char data;
    ListNode* next;
};

bool isEmpty(const ListNode* head) {
    return head == nullptr;
}

void insert(ListNode*& head, char value) {
    auto* newPtr = new ListNode{value, nullptr};
    ListNode* prev = nullptr;
    ListNode* curr = head;

    while (curr != nullptr && value > curr->data) {
        prev = curr;
        curr = curr->next;
    }

    if (prev == nullptr) {
        newPtr->next = head;
        head = newPtr;
    } else {
        prev->next = newPtr;
        newPtr->next = curr;
    }
}

char deleteNode(ListNode*& head, char value) {
    if (isEmpty(head)) {
        return '\0';
    }

    if (head->data == value) {
        ListNode* temp = head;
        head = head->next;
        delete temp;
        return value;
    }

    ListNode* prev = head;
    ListNode* curr = head->next;
    while (curr != nullptr && curr->data != value) {
        prev = curr;
        curr = curr->next;
    }

    if (curr != nullptr) {
        ListNode* temp = curr;
        prev->next = curr->next;
        delete temp;
        return value;
    }

    return '\0';
}

void printList(const ListNode* head) {
    if (isEmpty(head)) {
        std::cout << "List is empty.\n";
        return;
    }
    std::cout << "The list is: ";
    const ListNode* curr = head;
    while (curr != nullptr) {
        std::cout << curr->data << " --> ";
        curr = curr->next;
    }
    std::cout << "NULL\n";
}

void freeList(ListNode*& head) {
    while (head != nullptr) {
        ListNode* temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    ListNode* list = nullptr;

    // Insert characters in arbitrary order: B, A, C
    insert(list, 'B');
    insert(list, 'A');
    insert(list, 'C');
    printList(list);

    // Delete an element
    char delVal = 'B';
    if (deleteNode(list, delVal) != '\0') {
        std::cout << delVal << " deleted.\n";
    }
    printList(list);

    // Clean up
    freeList(list);
    return 0;
}
